// Register creates a new user account in the Balkan Drive system.
// It validates the input parameters, hashes the password using bcrypt,
// and stores the user in the database with the specified role.
// If no role is provided, it defaults to 'user'.
//
// Returns an AuthPayload containing a JWT token and user information
// upon successful registration. The JWT token expires after 24 hours.
//
// Parameters:
//   - username: Unique username for the new account
//   - email: Email address for the new account
//   - password: Plain text password (will be hashed)
//   - role: User role (defaults to 'user' if empty)
//
// Returns error if username/email already exists or database operation fails.
func (r *mutationResolver) Register(ctx context.Context, username string, email string, password string, role string) (*model.AuthPayload, error) {
	// Hash password
	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return nil, fmt.Errorf("failed to hash password: %v", err)
	}

	// Create user with specified role (default to 'user' if empty)
	if role == "" {
		role = "user"
	}

	user := &model.User{}
	err = r.DB.QueryRow(ctx,
		"INSERT INTO users (username, email, password, role, created_at) VALUES ($1, $2, $3, $4, NOW()) RETURNING id, username, email, role",
		username, email, string(hashedPassword), role).Scan(&user.ID, &user.Username, &user.Email, &user.Role)
	if err != nil {
		// Check for unique constraint violations
		if pgErr, ok := err.(*pgconn.PgError); ok {
			if pgErr.Code == "23505" { // unique_violation
				if strings.Contains(pgErr.Detail, "username") {
					return nil, fmt.Errorf("username already exists")
				}
				if strings.Contains(pgErr.Detail, "email") {
					return nil, fmt.Errorf("email already exists")
				}
			}
		}
		return nil, fmt.Errorf("failed to create user: %v", err)
	}

	// Create JWT token with proper claims
	cfg := config.Load()
	claims := &middleware.Claims{
		UserID:   user.ID,
		Username: user.Username,
		Email:    user.Email,
		Role:     user.Role,
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	tokenString, err := token.SignedString([]byte(cfg.JWTSecret))
	if err != nil {
		return nil, fmt.Errorf("failed to sign token: %v", err)
	}

	return &model.AuthPayload{
		Token: tokenString,
		User:  user,
	}, nil
}

// Login is the resolver for the login field.
// Login authenticates a user and returns a JWT token for accessing the Balkan Drive system.
// It validates the provided email and password against stored credentials using bcrypt
// for secure password comparison.
//
// The returned JWT token contains user claims and expires after 24 hours.
// This token must be included in subsequent requests for authentication.
//
// Parameters:
//   - email: User's email address
//   - password: User's plain text password
//
// Returns AuthPayload with JWT token and user information on success.
// Returns error if credentials are invalid or user doesn't exist.
func (r *mutationResolver) Login(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	var user model.User
	var hashedPassword string

	err := r.DB.QueryRow(ctx,
		"SELECT id, username, email, password, COALESCE(role, 'user') FROM users WHERE email = $1",
		email).Scan(&user.ID, &user.Username, &user.Email, &hashedPassword, &user.Role)
	if err != nil {
		return nil, fmt.Errorf("invalid credentials")
	}

	// Verify password
	if err := bcrypt.CompareHashAndPassword([]byte(hashedPassword), []byte(password)); err != nil {
		return nil, fmt.Errorf("invalid credentials")
	}

	// Create JWT token
	cfg := config.Load()
	claims := &middleware.Claims{
		UserID:   user.ID,
		Username: user.Username,
		Email:    user.Email,
		Role:     user.Role,
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(24 * time.Hour)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	tokenString, err := token.SignedString([]byte(cfg.JWTSecret))
	if err != nil {
		return nil, fmt.Errorf("failed to sign token: %v", err)
	}

	return &model.AuthPayload{
		Token: tokenString,
		User:  &user,
	}, nil
}

// ChangePassword updates the current user's password after validating their current password.
// This mutation requires the user to be authenticated and provide their current password
// for security verification before setting the new password.
//
// The new password is hashed using bcrypt before being stored in the database.
// This operation also logs an audit trail entry for security monitoring.
//
// Parameters:
//   - oldPassword: Current password for verification
//   - newPassword: New password to set (will be hashed)
//
// Returns true on successful password change.
// Returns error if user is not authenticated, old password is incorrect,
// or database operation fails.
func (r *mutationResolver) ChangePassword(ctx context.Context, oldPassword string, newPassword string) (bool, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	var currentPassword string
	err = r.DB.QueryRow(ctx, "SELECT password FROM users WHERE id = $1", user.ID).Scan(&currentPassword)
	if err != nil {
		return false, fmt.Errorf("user not found: %v", err)
	}

	// Verify old password
	if err := bcrypt.CompareHashAndPassword([]byte(currentPassword), []byte(oldPassword)); err != nil {
		return false, fmt.Errorf("invalid old password")
	}

	// Hash new password
	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(newPassword), bcrypt.DefaultCost)
	if err != nil {
		return false, fmt.Errorf("failed to hash password: %v", err)
	}

	// Update password
	_, err = r.DB.Exec(ctx, "UPDATE users SET password = $1 WHERE id = $2", string(hashedPassword), user.ID)
	if err != nil {
		return false, fmt.Errorf("failed to update password: %v", err)
	}

	return true, nil
}

// UploadFile initiates a file upload process to AWS S3 and prepares the file metadata.
// This mutation handles the first phase of file upload by generating a secure upload URL
// and storing preliminary file information. The actual file content is uploaded directly
// to S3 using the returned upload URL.
//
// The function implements deduplication by checking file hashes - if a file with the same
// content already exists, it creates a new file record pointing to the existing content
// to save storage space.
//
// Parameters:
//   - filename: Name of the file being uploaded
//   - filetype: MIME type of the file
//   - filePath: Virtual path where the file should be stored
//   - filesize: Size of the file in bytes
//   - isPublic: Whether the file should be publicly accessible
//   - file: GraphQL upload containing file metadata and content
//
// Returns UploadIntent with upload token and S3 upload URL for completing the upload.
// Returns error if user is not authenticated, S3 configuration fails, or database operation fails.
func (r *mutationResolver) UploadFile(ctx context.Context, filename string, filetype string, filePath string, filesize int32, isPublic bool, file graphql.Upload) (*model.UploadIntent, error) {
	// Load config
	cfg := config.Load()

	// Get authenticated user
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// Read file content for hashing while preserving original stream
	hash := sha256.New()
	var fileContent bytes.Buffer
	
	// Create a multi-writer to hash and buffer simultaneously
	multiWriter := io.MultiWriter(hash, &fileContent)
	
	// Copy the file content to both hash and buffer
	if _, err := io.Copy(multiWriter, file.File); err != nil {
		return nil, fmt.Errorf("failed to read file content: %v", err)
	}
	
	filehash := hex.EncodeToString(hash.Sum(nil))
	
	// Use the original file size from the frontend (this is the actual file size)
	actualFileSize := int64(filesize)
	
	// Get the size of what we read into the buffer
	bufferSize := int64(fileContent.Len())
	
	// Log any size discrepancies for debugging
	if bufferSize != actualFileSize {
		log.Printf("File size discrepancy for %s: frontend_reported=%d, buffer_read=%d", 
			filename, actualFileSize, bufferSize)
	}
	var refCount int
	var existingStorageKey string
	err = r.DB.QueryRow(ctx,
		`SELECT ref_count, storage_key FROM content WHERE sha256 = $1`,
		filehash,
	).Scan(&refCount, &existingStorageKey)

	contentExists := err == nil
	if err != nil && err != pgx.ErrNoRows {
		return nil, fmt.Errorf("failed to check content: %v", err)
	}
	sess, err := session.NewSession(&aws.Config{
		Region: aws.String(cfg.AWSRegion),
		Credentials: credentials.NewStaticCredentials(
			cfg.AWSAccessKeyID,
			cfg.AWSSecretAccessKey,
			"", // token not needed for static credentials
		),
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create AWS session: %v", err)
	}
	s3Client := s3.New(sess)
	var storageKey string
	var uploadURL string
	if contentExists {
		storageKey = existingStorageKey
		_, err = r.DB.Exec(ctx,
			`UPDATE content SET ref_count = ref_count + 1 WHERE sha256 = $1`,
			filehash,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to update ref_count: %v", err)
		}
		req, _ := s3Client.GetObjectRequest(&s3.GetObjectInput{
			Bucket: aws.String(cfg.S3Bucket),
			Key:    aws.String(storageKey),
		})
		uploadURL, err = req.Presign(15 * time.Minute)
		if err != nil {
			return nil, fmt.Errorf("failed to presign download URL: %v", err)
		}
	} else {
		storageKey = "uploads/" + filehash
		_, err = s3Client.PutObject(&s3.PutObjectInput{
			Bucket:      aws.String(cfg.S3Bucket),
			Key:         aws.String(storageKey),
			Body:        bytes.NewReader(fileContent.Bytes()),
			ContentType: aws.String(filetype),
		})
		if err != nil {
			return nil, fmt.Errorf("failed to upload file to S3: %v", err)
		}
		req, _ := s3Client.GetObjectRequest(&s3.GetObjectInput{
			Bucket: aws.String(cfg.S3Bucket),
			Key:    aws.String(storageKey),
		})
		uploadURL, err = req.Presign(15 * time.Minute)
		if err != nil {
			return nil, fmt.Errorf("failed to presign download URL: %v", err)
		}
		_, err = r.DB.Exec(ctx,
			`INSERT INTO content (sha256, storage_key, size_bytes, ref_count, created_at)
             VALUES ($1, $2, $3, $4, NOW())`,
			filehash, storageKey, actualFileSize, 1,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to insert content: %v", err)
		}
	}
	var fileRecord model.File
	err = r.DB.QueryRow(ctx,
		`INSERT INTO files (filename, filetype, filesize, filehash, is_public, owner_id, created_at)
         VALUES ($1, $2, $3, $4, $5, $6, NOW())
         RETURNING id, filename, filetype, filesize, filehash, is_public`,
		filename, filetype, actualFileSize, filehash, isPublic, user.ID,
	).Scan(
		&fileRecord.ID,
		&fileRecord.Filename,
		&fileRecord.Filetype,
		&fileRecord.Filesize,
		&fileRecord.Filehash,
		&fileRecord.IsPublic,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to insert file: %v", err)
	}
	return &model.UploadIntent{
		UploadURL:   uploadURL,
		UploadToken: filehash,
	}, nil
}

// CompleteUpload is the resolver for the completeUpload field.
// CompleteUpload finalizes a file upload operation after the file has been uploaded to S3.
// This mutation is called after the client successfully uploads the file content to the
// S3 URL provided by UploadFile. It validates the upload token and creates the final
// file record in the database.
//
// The function also creates an audit log entry to track the file upload for security
// and compliance purposes.
//
// Parameters:
//   - uploadToken: Secure token generated during the UploadFile phase
//
// Returns the completed File object with all metadata.
// Returns error if upload token is invalid, expired, or database operation fails.
func (r *mutationResolver) CompleteUpload(ctx context.Context, uploadToken string) (*model.File, error) {
	// Find file by hash (uploadToken)
	var file model.File
	var createdAt time.Time
	var ownerID string
	err := r.DB.QueryRow(ctx,
		`SELECT id, filename, filetype, filesize, filehash, is_public, created_at, owner_id
		 FROM files WHERE filehash = $1 ORDER BY created_at DESC LIMIT 1`,
		uploadToken,
	).Scan(&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash, &file.IsPublic, &createdAt, &ownerID)

	if err != nil {
		return nil, fmt.Errorf("upload not found: %v", err)
	}

	// Convert timestamp to string
	file.CreatedAt = createdAt.Format(time.RFC3339)

	// Generate filepath (this could be the S3 key or URL)
	file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

	// Get owner information
	var owner model.User
	err = r.DB.QueryRow(ctx,
		"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
		ownerID,
	).Scan(&owner.ID, &owner.Username, &owner.Email, &owner.Role)

	if err != nil {
		return nil, fmt.Errorf("failed to get owner: %v", err)
	}

	file.Owner = &owner

	// Log file upload audit event
	err = r.AuditLogger.LogFileUpload(ctx, ownerID,
		file.ID, file.Filename, int64(file.Filesize), file.Filetype, nil)
	if err != nil {
		// Log error but don't fail the upload
		log.Printf("Audit logging error: %v", err)
	}

	return &file, nil
}

// DeleteFile is the resolver for the deleteFile field.
// DeleteFile permanently removes a file from the Balkan Drive system.
// This mutation deletes the file record from the database and decrements the reference
// count for the associated content. If the content is no longer referenced by any files,
// it may be eligible for garbage collection from S3 storage.
//
// Only the file owner or users with appropriate permissions can delete files.
// This operation also removes any existing file shares and creates an audit log entry.
//
// Parameters:
//   - fileID: Unique identifier of the file to delete
//
// Returns true on successful deletion.
// Returns error if user lacks permission, file doesn't exist, or database operation fails.
func (r *mutationResolver) DeleteFile(ctx context.Context, fileID string) (bool, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	// Check if user owns the file and get file details for audit
	var ownerID, filehash, filename string
	err = r.DB.QueryRow(ctx, "SELECT owner_id, filehash, filename FROM files WHERE id = $1", fileID).Scan(&ownerID, &filehash, &filename)
	if err != nil {
		return false, fmt.Errorf("file not found: %v", err)
	}

	if ownerID != user.ID {
		return false, fmt.Errorf("you can only delete your own files")
	}

	// Log file deletion audit event before deletion
	err = r.AuditLogger.LogFileDelete(ctx, user.ID, fileID, filename, nil)
	if err != nil {
		log.Printf("Audit logging error for delete: %v", err)
	}

	// Delete file record
	_, err = r.DB.Exec(ctx, "DELETE FROM files WHERE id = $1", fileID)
	if err != nil {
		return false, fmt.Errorf("failed to delete file: %v", err)
	}

	// Decrement reference count and delete from S3 if no more references
	var refCount int
	var storageKey string
	err = r.DB.QueryRow(ctx,
		"UPDATE content SET ref_count = ref_count - 1 WHERE sha256 = $1 RETURNING ref_count, storage_key",
		filehash,
	).Scan(&refCount, &storageKey)

	if err != nil {
		return false, fmt.Errorf("failed to update content: %v", err)
	}

	// If no more references, delete from S3 and content table
	if refCount <= 0 {
		cfg := config.Load()

		// Delete from S3
		sess, _ := session.NewSession(&aws.Config{
			Region: aws.String(cfg.AWSRegion),
			Credentials: credentials.NewStaticCredentials(
				cfg.AWSAccessKeyID,
				cfg.AWSSecretAccessKey,
				"", // token not needed for static credentials
			),
		})
		s3Client := s3.New(sess)

		_, err = s3Client.DeleteObject(&s3.DeleteObjectInput{
			Bucket: aws.String(cfg.S3Bucket),
			Key:    aws.String(storageKey),
		})
		if err != nil {
			// Log error but don't fail the operation
			log.Printf("Failed to delete from S3: %v", err)
		}

		// Delete content record
		_, err = r.DB.Exec(ctx, "DELETE FROM content WHERE sha256 = $1", filehash)
		if err != nil {
			return false, fmt.Errorf("failed to delete content: %v", err)
		}
	}

	return true, nil
}

// ChangeVisibility is the resolver for the changeVisibility field.
