// ShareFile is the resolver for the shareFile field.
// ShareFile grants access to a file for a specific user identified by user ID.
// This mutation creates a file share relationship between the file owner and the
// target user, allowing the target user to access the file according to the specified
// permission level.
//
// Valid permission levels include 'read' for view-only access and 'write' for
// read-write access. The relationship parameter determines the access level.
// Share relationships are logged for audit purposes.
//
// Parameters:
//   - fileID: Unique identifier of the file to share
//   - userID: ID of the user to share the file with
//   - relationship: Permission level ('read' or 'write')
//
// Returns the created FileShares object with share details.
// Returns error if user lacks permission, file/user doesn't exist, or database operation fails.
func (r *mutationResolver) ShareFile(ctx context.Context, fileID string, userID string, relationship string) (*model.FileShares, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	var share model.FileShares
	err = r.DB.QueryRow(ctx,
		`INSERT INTO file_shares (file_id, shared_with, permission, shared_by, created_at)
		 VALUES ($1, $2, $3, $4, NOW())
		 RETURNING id`,
		fileID, userID, relationship, user.ID,
	).Scan(&share.ID)

	if err != nil {
		return nil, fmt.Errorf("failed to share file: %v", err)
	}

	// Populate the complete FileShares object
	share.Permission = relationship

	// Get the file information
	var file model.File
	var createdAt time.Time
	var fileOwnerID string
	err = r.DB.QueryRow(ctx,
		"SELECT id, filename, filetype, filesize, filehash, is_public, created_at, owner_id FROM files WHERE id = $1",
		fileID,
	).Scan(&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash, &file.IsPublic, &createdAt, &fileOwnerID)
	if err != nil {
		return nil, fmt.Errorf("failed to get file: %v", err)
	}

	file.CreatedAt = createdAt.Format(time.RFC3339)
	file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

	// Get file owner information
	var fileOwner model.User
	err = r.DB.QueryRow(ctx,
		"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
		fileOwnerID,
	).Scan(&fileOwner.ID, &fileOwner.Username, &fileOwner.Email, &fileOwner.Role)
	if err != nil {
		return nil, fmt.Errorf("failed to get file owner: %v", err)
	}
	file.Owner = &fileOwner
	share.File = &file

	// Get the shared with user information
	var sharedWith model.User
	err = r.DB.QueryRow(ctx,
		"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
		userID,
	).Scan(&sharedWith.ID, &sharedWith.Username, &sharedWith.Email, &sharedWith.Role)
	if err != nil {
		return nil, fmt.Errorf("failed to get shared with user: %v", err)
	}
	share.SharedWith = &sharedWith

	// Set the shared by user (current user)
	share.SharedBy = &model.User{
		ID:       user.ID,
		Username: user.Username,
		Email:    user.Email,
		Role:     user.Role,
	}

	return &share, nil
}

// ShareFileByUsername is the resolver for the shareFileByUsername field.
// ShareFileByUsername grants access to a file for a specific user identified by username.
// This is a convenience mutation that works similarly to ShareFile but accepts a username
// instead of user ID. It first resolves the username to a user ID, then creates the
// file share relationship.
//
// This mutation is useful for user interfaces where usernames are more user-friendly
// than internal user IDs. All the same permission and auditing rules apply as ShareFile.
//
// Parameters:
//   - fileID: Unique identifier of the file to share
//   - username: Username of the user to share the file with
//   - permission: Permission level ('read' or 'write')
//
// Returns the created FileShares object with share details.
// Returns error if user lacks permission, file/username doesn't exist, or database operation fails.
func (r *mutationResolver) ShareFileByUsername(ctx context.Context, fileID string, username string, permission string) (*model.FileShares, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// First, find the user by username
	var targetUserID string
	err = r.DB.QueryRow(ctx,
		"SELECT id FROM users WHERE username = $1",
		username,
	).Scan(&targetUserID)
	if err != nil {
		return nil, fmt.Errorf("user not found: %v", err)
	}

	// Check if the file exists and the current user owns it
	var fileOwnerID string
	err = r.DB.QueryRow(ctx,
		"SELECT owner_id FROM files WHERE id = $1",
		fileID,
	).Scan(&fileOwnerID)
	if err != nil {
		return nil, fmt.Errorf("file not found: %v", err)
	}

	if fileOwnerID != user.ID {
		return nil, fmt.Errorf("permission denied: you can only share your own files")
	}

	// Create the share
	var share model.FileShares
	err = r.DB.QueryRow(ctx,
		`INSERT INTO file_shares (file_id, shared_with, permission, shared_by, created_at)
		 VALUES ($1, $2, $3, $4, NOW())
		 RETURNING id`,
		fileID, targetUserID, permission, user.ID,
	).Scan(&share.ID)

	if err != nil {
		return nil, fmt.Errorf("failed to share file: %v", err)
	}

	// Populate the complete FileShares object
	share.Permission = permission

	// Get the file information
	var file model.File
	var createdAt time.Time
	var fileOwnerIDForFile string
	err = r.DB.QueryRow(ctx,
		"SELECT id, filename, filetype, filesize, filehash, is_public, created_at, owner_id FROM files WHERE id = $1",
		fileID,
	).Scan(&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash, &file.IsPublic, &createdAt, &fileOwnerIDForFile)
	if err != nil {
		return nil, fmt.Errorf("failed to get file: %v", err)
	}

	file.CreatedAt = createdAt.Format(time.RFC3339)
	file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

	// Get file owner
	var fileOwner model.User
	err = r.DB.QueryRow(ctx,
		"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
		fileOwnerIDForFile,
	).Scan(&fileOwner.ID, &fileOwner.Username, &fileOwner.Email, &fileOwner.Role)
	if err != nil {
		return nil, fmt.Errorf("failed to get file owner: %v", err)
	}
	file.Owner = &fileOwner
	share.File = &file

	// Get the target user (shared with)
	var sharedWithUser model.User
	err = r.DB.QueryRow(ctx,
		"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
		targetUserID,
	).Scan(&sharedWithUser.ID, &sharedWithUser.Username, &sharedWithUser.Email, &sharedWithUser.Role)
	if err != nil {
		return nil, fmt.Errorf("failed to get shared user: %v", err)
	}
	share.SharedWith = &sharedWithUser

	// Set the current user as the one who shared
	share.SharedBy = &model.User{
		ID:       user.ID,
		Username: user.Username,
		Email:    user.Email,
		Role:     user.Role,
	}

	return &share, nil
}

// UnshareFile is the resolver for the unshareFile field.
// UnshareFile revokes file access for a specific user.
// This mutation removes an existing file share relationship, preventing the target
// user from accessing the file. Only file owners can unshare their files.
//
// The operation creates an audit log entry for tracking access revocation.
// If the specified share relationship doesn't exist, the operation still succeeds
// (idempotent behavior).
//
// Parameters:
//   - fileID: Unique identifier of the shared file
//   - userID: ID of the user whose access should be revoked
//
// Returns true on successful unshare operation.
// Returns error if user lacks permission, file doesn't exist, or database operation fails.
func (r *mutationResolver) UnshareFile(ctx context.Context, fileID string, userID string) (bool, error) {
	currentUser, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	// Check if the current user owns the file or is the user being unshared
	var ownerID string
	err = r.DB.QueryRow(ctx, "SELECT owner_id FROM files WHERE id = $1", fileID).Scan(&ownerID)
	if err != nil {
		return false, fmt.Errorf("file not found: %v", err)
	}

	result, err := r.DB.Exec(ctx,
		"DELETE FROM file_shares WHERE file_id = $1 AND shared_by = $2",
		fileID, currentUser.ID,
	)

	if err != nil {
		return false, fmt.Errorf("failed to unshare file: %v", err)
	}

	rowsAffected := result.RowsAffected()
	if rowsAffected == 0 {
		return false, fmt.Errorf("no file share found to remove")
	}

	return true, nil
}

// ShareFilePublicly is the resolver for the shareFilePublicly field.
// ShareFilePublicly makes a file accessible to all authenticated users.
// This mutation enables public sharing for a file, allowing any authenticated user
// in the system to discover and download the file. The file will appear in public
// file listings and search results.
//
// This operation sets the public sharing timestamp and records which user enabled
// public access for audit purposes. Only file owners can make their files public.
//
// Parameters:
//   - fileID: Unique identifier of the file to share publicly
//
// Returns true on successful public sharing activation.
// Returns error if user lacks permission, file doesn't exist, or database operation fails.
func (r *mutationResolver) ShareFilePublicly(ctx context.Context, fileID string) (bool, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	// Check if the user owns the file
	var ownerID string
	err = r.DB.QueryRow(ctx, "SELECT owner_id FROM files WHERE id = $1", fileID).Scan(&ownerID)
	if err != nil {
		return false, fmt.Errorf("file not found: %v", err)
	}

	if ownerID != user.ID {
		return false, fmt.Errorf("permission denied: you can only share your own files")
	}

	// Update the file to be publicly shared
	_, err = r.DB.Exec(ctx,
		"UPDATE files SET is_public_shared = TRUE, public_share_enabled_at = NOW(), public_share_enabled_by = $1 WHERE id = $2",
		user.ID, fileID)
	if err != nil {
		return false, fmt.Errorf("failed to share file publicly: %v", err)
	}

	return true, nil
}

// UnshareFilePublicly is the resolver for the unshareFilePublicly field.
// UnshareFilePublicly removes public access from a file.
// This mutation disables public sharing for a file, making it accessible only to
// the owner and users with explicit share permissions. The file will be removed
// from public listings and search results.
//
// This operation clears the public sharing metadata and creates an audit log entry.
// Only file owners can remove public access from their files.
//
// Parameters:
//   - fileID: Unique identifier of the file to make private
//
// Returns true on successful public sharing removal.
// Returns error if user lacks permission, file doesn't exist, or database operation fails.
func (r *mutationResolver) UnshareFilePublicly(ctx context.Context, fileID string) (bool, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	// Check if the user owns the file
	var ownerID string
	err = r.DB.QueryRow(ctx, "SELECT owner_id FROM files WHERE id = $1", fileID).Scan(&ownerID)
	if err != nil {
		return false, fmt.Errorf("file not found: %v", err)
	}

	if ownerID != user.ID {
		return false, fmt.Errorf("permission denied: you can only unshare your own files")
	}

	// Update the file to remove public sharing
	_, err = r.DB.Exec(ctx,
		"UPDATE files SET is_public_shared = FALSE, public_share_enabled_at = NULL, public_share_enabled_by = NULL WHERE id = $1",
		fileID)
	if err != nil {
		return false, fmt.Errorf("failed to unshare file publicly: %v", err)
	}

	return true, nil
}

// DownloadPublicFile is the resolver for the downloadPublicFile field.
// DownloadPublicFile generates a secure download URL for a publicly shared file.
// This mutation creates a time-limited, pre-signed URL that allows downloading
// the file content from S3 storage. The file must be publicly shared to use this endpoint.
//
// Each download is tracked for statistics and audit purposes, recording the downloader's
// information and access timestamp. The generated URL expires after a short period
// for security reasons.
//
// Parameters:
//   - fileID: Unique identifier of the public file to download
//
// Returns a secure download URL string.
// Returns error if file is not public, doesn't exist, or S3 operation fails.
func (r *mutationResolver) DownloadPublicFile(ctx context.Context, fileID string) (string, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return "", fmt.Errorf("authentication required: %v", err)
	}

	// Check if the file is publicly shared
	var isPublicShared bool
	var filehash string
	err = r.DB.QueryRow(ctx,
		"SELECT is_public_shared, filehash FROM files WHERE id = $1",
		fileID).Scan(&isPublicShared, &filehash)
	if err != nil {
		return "", fmt.Errorf("file not found: %v", err)
	}

	if !isPublicShared {
		return "", fmt.Errorf("file is not publicly shared")
	}

	// Record the download
	_, err = r.DB.Exec(ctx,
		"INSERT INTO file_downloads (file_id, downloaded_by, ip_address) VALUES ($1, $2, $3)",
		fileID, user.ID, "unknown") // TODO: Extract real IP from context
	if err != nil {
		log.Printf("Failed to record download: %v", err)
		// Don't fail the download if recording fails
	}

	// Generate download URL using S3
	cfg := config.Load()
	sess, err := session.NewSession(&aws.Config{
		Region: aws.String(cfg.AWSRegion),
	})
	if err != nil {
		return "", fmt.Errorf("failed to create AWS session: %v", err)
	}

	svc := s3.New(sess)
	req, _ := svc.GetObjectRequest(&s3.GetObjectInput{
		Bucket: aws.String(cfg.S3Bucket),
		Key:    aws.String(fmt.Sprintf("uploads/%s", filehash)),
	})

	// Generate a presigned URL valid for 1 hour
	url, err := req.Presign(time.Hour)
	if err != nil {
		return "", fmt.Errorf("failed to generate download URL: %v", err)
	}

	return url, nil
}

